function validate([nums1, nums2]) {
  for (const [name, nums] of [['nums1', nums1], ['nums2', nums2]]) {
    if (nums.length < 1 || nums.length > 100000) return `${name} needs 1 to 10^5 values.`;
    for (let i = 0; i < nums.length; i++) {
      if (!Number.isInteger(nums[i]) || nums[i] < 1 || nums[i] > 1000000000) return `Each value of ${name} is between 1 and 10^9.`;
      if (i > 0 && nums[i] < nums[i - 1]) return `${name} must be sorted in non-decreasing order.`;
    }
  }
  return null;
}

