function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const span = large ? (rand() < 0.5 ? 1000000000 : pick(2000, 20000)) : pick(1, 12);
  const make = (length) => Array.from({ length }, () => pick(1, span)).sort((a, b) => a - b);
  const nums1 = make(large ? 2000 : pick(1, 6));
  const nums2 = make(large ? 2000 : pick(1, 6));
  // Large random arrays rarely share a value, so sometimes plant one in both.
  if (large && rand() < 0.5) {
    const shared = pick(1, span);
    nums1[pick(0, nums1.length - 1)] = shared;
    nums2[pick(0, nums2.length - 1)] = shared;
    nums1.sort((a, b) => a - b);
    nums2.sort((a, b) => a - b);
  }
  return [nums1, nums2];
}
